22	/**
23	 * Adjusts dates so that they fall on a business day: a weekday (Monday to Friday) that is not a
24	 * listed public holiday.
25	 */
26	public final class BusinessDayAdjuster {
27	
28	    private BusinessDayAdjuster() {
29	    }
30	
31	    /**
32	     * Return the given date if it already falls on a business day, otherwise roll it forward to the
33	     * next business day. A Saturday, Sunday or {@link PublicHolidays public holiday} is rolled
34	     * forward one day at a time until a non-holiday weekday is reached.
35	     *
36	     * @param date the date to adjust
37	     * @return the date rolled forward to the next business day, or {@code null} if {@code date} is
38	     *     {@code null}
39	     */
40	    public static LocalDate toBusinessDay(LocalDate date) {
41	        if (date == null) {
42	            return null;
43	        }
44	        while (!isBusinessDay(date)) {
45	            date = date.plusDays(1);
46	        }
47	        return date;
48	    }
49	
50	    private static boolean isBusinessDay(LocalDate date) {
51	        DayOfWeek dayOfWeek = date.getDayOfWeek();
52	        return dayOfWeek != DayOfWeek.SATURDAY && dayOfWeek != DayOfWeek.SUNDAY
53	                && !PublicHolidays.isHoliday(date);
54	    }
